package com.zerotrust.internalresource.audit;
import com.zerotrust.internalresource.config.ResourceSecurityProperties;import com.zerotrust.internalresource.entity.AccessLogEntity;import com.zerotrust.internalresource.repository.AccessLogRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.time.Instant;
@Component("resourceAuditFilter") @Order(Ordered.HIGHEST_PRECEDENCE+1) public class RequestAuditFilter extends OncePerRequestFilter{private final AccessLogRepository repository;private final GatewayAccessEvaluator gateway;private final ResourceIdResolver resolver;private final ResourceSecurityProperties properties;public RequestAuditFilter(AccessLogRepository repository,GatewayAccessEvaluator gateway,ResourceIdResolver resolver,ResourceSecurityProperties properties){this.repository=repository;this.gateway=gateway;this.resolver=resolver;this.properties=properties;}protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{long start=System.nanoTime();try{chain.doFilter(request,response);}finally{if(properties.isAuditEnabled()&&request.getRequestURI().startsWith("/api/")){save(request,response,start);}}}private void save(HttpServletRequest request,HttpServletResponse response,long start){try{var log=new AccessLogEntity();log.setTraceId((String)request.getAttribute(RequestContextFilter.TRACE_ID_ATTRIBUTE));log.setRequestId((String)request.getAttribute(RequestContextFilter.REQUEST_ID_ATTRIBUTE));log.setRequestPath(request.getRequestURI());log.setHttpMethod(request.getMethod());log.setActualRemoteAddr(request.getRemoteAddr());log.setForwardedFor(request.getHeader("X-Forwarded-For"));log.setUserAgent(request.getHeader("User-Agent"));log.setSessionIdPresent(request.getHeader("X-Session-Id")!=null);log.setDeviceFingerprintPresent(request.getHeader("X-Device-Fingerprint")!=null);log.setAuthorizationPresent(request.getHeader("Authorization")!=null);log.setResourceId(resolver.resolve(request));log.setGatewayAccess(gateway.isGatewayAccess(request));log.setResponseStatus(response.getStatus());Object auditResult=request.getAttribute(DirectAccessFilter.AUDIT_RESULT_ATTRIBUTE);log.setResult(auditResult==null?(response.getStatus()<400?"SUCCESS":"REJECTED"):auditResult.toString());log.setProcessingTime((System.nanoTime()-start)/1_000_000);log.setCreatedAt(Instant.now());repository.save(log);}catch(RuntimeException ignored){}}}

